package ls.augment.com.hook;

import android.content.Context;
import android.net.Uri;
import android.os.Bundle;
import android.os.ParcelFileDescriptor;
import java.io.Closeable;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import ls.augment.com.BuildConfig;

/** Read-only host client. Generated bytes belong exclusively to the module provider. */
final class ComboMotionFileScaler {
    static final long MAX_FILE_BYTES = 16L * 1024L * 1024L;
    static final String ALGORITHM_VERSION = "motion-time-v3";
    private static final Uri PROVIDER = Uri.parse("content://ls.augment.com.config");
    private static final ComboMotionLeases<MotionDescriptor> LEASES = new ComboMotionLeases<>();
    private ComboMotionFileScaler() { }

    static Result scale(Context context, ComboMotionCache.Request request) {
        if (context == null || request == null || !request.valid) return Result.failure("invalid_request");
        try (ParcelFileDescriptor source = ParcelFileDescriptor.open(
                new File(request.normalizedPath), ParcelFileDescriptor.MODE_READ_ONLY)) {
            Bundle args = new Bundle();
            args.putInt("version", BuildConfig.VERSION_CODE);
            args.putParcelable("source", source);
            args.putString("source_id", hex(MessageDigest.getInstance("SHA-256").digest(
                    request.normalizedPath.getBytes(StandardCharsets.UTF_8))));
            args.putString("digest", request.contentDigest);
            args.putLong("size", request.size);
            args.putLong("modified", request.modifiedAt);
            args.putFloat("rate", request.rate);
            Bundle reply = context.getContentResolver().call(PROVIDER, "combo_motion_prepare", null, args);
            if (reply == null || !reply.getBoolean("ok", false)
                    || reply.getInt("version", -1) != BuildConfig.VERSION_CODE)
                return Result.failure(reply == null ? "provider_unavailable" : reply.getString("error", "provider_rejected"));
            String identity = reply.getString("identity", "");
            int events = reply.getInt("events", 0);
            long span = reply.getLong("source_span", -1), output = reply.getLong("output_span", -1);
            if (!identity.matches("[0-9a-f]{64}") || events <= 0 || span < 0 || output < 0 || output > span)
                return Result.failure("invalid_provider_result");
            Uri uri = PROVIDER.buildUpon().appendPath("combo-motion").appendPath(identity).build();
            ParcelFileDescriptor descriptor = context.getContentResolver().openFileDescriptor(uri, "r");
            if (descriptor == null) return Result.failure("descriptor_missing");
            ComboMotionLeases.Lease<MotionDescriptor> lease = LEASES.register(
                    new MotionDescriptor(context, uri, descriptor, request.normalizedPath));
            if (lease == null) return Result.failure("descriptor_limit");
            return new Result(true, reply.getBoolean("cache_hit", false), lease.path, identity,
                    events, span, output, reply.getString("evidence", "PRIVATE_CACHE"), "", lease);
        } catch (Exception error) { return Result.failure(error.getClass().getSimpleName()); }
    }

    static boolean pin(Object owner, Result result) {
        return result != null && result.isUsable() && LEASES.pin(owner, result.lease);
    }
    static void releasePlayback(Object owner) { LEASES.release(owner); }
    static boolean isVirtualPath(String path) { return path != null && path.startsWith(ComboMotionLeases.PREFIX); }

    /** Runs inside the existing OEM provider, preserving its Binder permissions and URI routing. */
    static Bundle openNative(String path) {
        Bundle result = new Bundle();
        try {
            MotionDescriptor copy = LEASES.duplicate(path, MotionDescriptor::reopen);
            if (copy != null) result.putParcelable("fd", copy.descriptor);
        } catch (Exception ignored) { }
        return result;
    }

    private static final class MotionDescriptor implements Closeable {
        final Context context;
        final Uri uri;
        final ParcelFileDescriptor descriptor;
        final String originalPath;
        volatile boolean available = true;
        MotionDescriptor(Context context, Uri uri, ParcelFileDescriptor descriptor, String originalPath) {
            this.context=context; this.uri=uri; this.descriptor=descriptor; this.originalPath=originalPath;
        }
        MotionDescriptor reopen() throws IOException {
            // dup() shares its file offset with previous readers. A fresh provider open gives
            // each playback an independent offset; never reopen the private inode in the host.
            ParcelFileDescriptor next;
            try {
                next = context.getContentResolver().openFileDescriptor(uri, "r");
                if (next == null) throw new IOException("motion_retired");
            } catch (Exception unavailable) {
                // Cache eviction/reset can unlink a prepared file before native requests it.
                // Keep this playback on its OEM original and rebuild on the next request.
                available = false;
                next = ParcelFileDescriptor.open(new File(originalPath), ParcelFileDescriptor.MODE_READ_ONLY);
            }
            return new MotionDescriptor(context, uri, next, originalPath);
        }
        @Override public void close() throws IOException { descriptor.close(); }
    }

    static String contentDigest(File source, long maximumBytes) throws Exception {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        try (FileInputStream input = new FileInputStream(source)) {
            byte[] buffer = new byte[8192]; long total = 0; int read;
            while ((read = input.read(buffer)) != -1) {
                total += read; if (total > maximumBytes) throw new IOException("motion_too_large");
                digest.update(buffer, 0, read);
            }
        }
        return hex(digest.digest());
    }
    private static String hex(byte[] bytes) {
        StringBuilder out = new StringBuilder(bytes.length * 2);
        for (byte item : bytes) out.append(String.format(java.util.Locale.ROOT, "%02x", item & 255));
        return out.toString();
    }

    static final class Result {
        final boolean success, cacheHit;
        final String outputPath, cacheIdentity, evidenceSource, error;
        final int eventCount;
        final long sourceSpanMs, outputSpanMs;
        private final ComboMotionLeases.Lease<MotionDescriptor> lease;
        private Result(boolean success, boolean cacheHit, String outputPath, String cacheIdentity,
                int eventCount, long sourceSpanMs, long outputSpanMs, String evidenceSource,
                String error, ComboMotionLeases.Lease<MotionDescriptor> lease) {
            this.success=success; this.cacheHit=cacheHit; this.outputPath=outputPath;
            this.cacheIdentity=cacheIdentity; this.eventCount=eventCount; this.sourceSpanMs=sourceSpanMs;
            this.outputSpanMs=outputSpanMs; this.evidenceSource=evidenceSource; this.error=error; this.lease=lease;
        }
        Result asPublishedHit() {
            return success ? new Result(true, true, outputPath, cacheIdentity, eventCount,
                    sourceSpanMs, outputSpanMs, "MEMORY_CACHE", "", lease) : this;
        }
        boolean isUsable() { return success && lease != null && lease.resource.available; }
        void retire() { LEASES.retire(lease); }
        static Result failure(String error) { return new Result(false,false,"","",0,0,0,"UNKNOWN",error,null); }
    }
}
